/**
 * Extract the scraped data and organize it nicely
 * Makes it easy to understand what was found
 */

// Create empty result structure
const result = {
  url: $('When clicking ‘Execute workflow’').first().json.url,
  title: null,
  h1_headings: [],
  h2_headings: [],
  paragraphs: [],
};

// Loop through each selector's results
const data = $json.data || "";

for (const item of data) {
  const selector = item.selector;
  const results = item.results || [];

  // Extract title
  if (selector === "title" && results.length > 0) {
    result.title = (results[0].text || "").trim();
  }

  // Extract H1 headings
  else if (selector === "h1") {
    result.h1_headings = results
      .map((r) => (r.text || "").trim())
      .filter((text) => text.length > 0);
  }

  // Extract H2 headings
  else if (selector === "h2") {
    result.h2_headings = results
      .map((r) => (r.text || "").trim())
      .filter((text) => text.length > 0);
  }

  // Extract paragraphs (limit to first 10)
  else if (selector === "p") {
    result.paragraphs = results
      .map((r) => (r.text || "").trim())
      .filter((text) => text.length > 0)
      .slice(0, 10); // Only keep first 10 paragraphs
  }
}

return result;
